// Rebuild the receive_invoice_link body, adding qbo_payment_link when QuickBooks returned one.
// ERPNext accepts only an https link on an intuit.com host (anything else is refused with 400
// invalid_payment_link and nothing is saved), so anything else is left out here.
const item = $input.item.json;
const body = { sales_invoice: item.sales_invoice, qbo_invoice_id: String(item.qbo_invoice_id) };
if (item.customer_qbo_id) body.customer_qbo_id = String(item.customer_qbo_id);

const link = String((item.Invoice && item.Invoice.InvoiceLink) || '').trim();
let host = '';
try { host = new URL(link).hostname.toLowerCase(); } catch (e) {}
if (link.startsWith('https://') && (host === 'intuit.com' || host.endsWith('.intuit.com')) && link.length <= 500) {
  body.qbo_payment_link = link;
}
return { json: body };
